/// Apply SVG group transform, crop to ink bounds (+2% pad), map into unit.
(List<Path>, double) _packFills(List<String> data, Float64List source) {
  final placed = [for (final d in data) _parseSvgPath(d).transform(source)];
  var bounds = placed.first.getBounds();
  for (final path in placed.skip(1)) {
    bounds = bounds.expandToInclude(path.getBounds());
  }
  final pad = bounds.longestSide * 0.02;
  bounds = Rect.fromLTRB(
    bounds.left - pad,
    bounds.top - pad,
    bounds.right + pad,
    bounds.bottom + pad,
  );
  final aspect = bounds.width / bounds.height;
  final toUnit = Float64List.fromList([
    1 / bounds.width, 0, 0, 0, //
    0, 1 / bounds.height, 0, 0, //
    0, 0, 1, 0, //
    -bounds.left / bounds.width, -bounds.top / bounds.height, 0, 1, //
  ]);
  return ([for (final path in placed) path.transform(toUnit)], aspect);
}

final _token = RegExp(r'[MmLlCcZz]|-?\d*\.?\d+(?:[eE][-+]?\d+)?');

Path _parseSvgPath(String data) {
  final tokens =
      _token.allMatches(data).map((match) => match.group(0)!).toList();
  final path = Path();
  var index = 0;
  var command = '';
  var x = 0.0;
  var y = 0.0;
  var startX = 0.0;
  var startY = 0.0;

  double next() => double.parse(tokens[index++]);

  while (index < tokens.length) {
    final token = tokens[index];
    if (RegExp(r'^[A-Za-z]$').hasMatch(token)) {
      command = token;
      index++;
      if (command == 'Z' || command == 'z') {
        path.close();
        x = startX;
        y = startY;
        command = '';
        continue;
      }
    }
    switch (command) {
      case 'M':
      case 'm':
        final relative = command == 'm';
        x = relative ? x + next() : next();
        y = relative ? y + next() : next();
        path.moveTo(x, y);
        startX = x;
        startY = y;
        command = relative ? 'l' : 'L';
      case 'L':
      case 'l':
        final relative = command == 'l';
        x = relative ? x + next() : next();
        y = relative ? y + next() : next();
        path.lineTo(x, y);
      case 'C':
      case 'c':
        final relative = command == 'c';
        final x1 = relative ? x + next() : next();
        final y1 = relative ? y + next() : next();
        final x2 = relative ? x + next() : next();
        final y2 = relative ? y + next() : next();
        final x3 = relative ? x + next() : next();
        final y3 = relative ? y + next() : next();
        path.cubicTo(x1, y1, x2, y2, x3, y3);
        x = x3;
        y = y3;
      default:
        index++;
    }
  }
  return path;
}

